INSERT INTO "publicaciones_publicacion" VALUES('4150fba47c084b7c8db1b56d2812d66d','Diseño de logotipo profesional para tu marca','Creo logotipos únicos y memorables que representan la esencia de tu marca. Incluye investigación de mercado, 3 propuestas iniciales, revisiones ilimitadas y entrega en formatos vectoriales (AI, SVG, PNG, PDF).','diseno',250000,'5 días','["3 propuestas iniciales", "Revisiones ilimitadas", "Archivos fuente AI/SVG", "Manual de marca b\u00e1sico"]','','publicado','2026-03-25 03:41:22.881926','2026-03-25 03:41:22.881946','e38db71366f748d6b2b7f7946bc709d4');
INSERT INTO "publicaciones_publicacion" VALUES('81e919a189604c21af6e47b1e0b4e74d','Desarrollo de landing page con React y Tailwind','Desarrollo landing pages modernas, responsivas y optimizadas para conversión. Uso React, Next.js y Tailwind CSS para garantizar rendimiento y diseño impecable. Incluye formulario de contacto funcional y despliegue.','desarrollo',800000,'7 días','["Dise\u00f1o responsivo", "SEO b\u00e1sico", "Formulario de contacto", "Deploy en Vercel"]','','publicado','2026-03-25 03:41:22.884211','2026-03-25 03:41:22.884228','967369eac6564d539dc06d43373a2a57');
INSERT INTO "publicaciones_publicacion" VALUES('55a36174c69f4ae68a4a3c60ab1f2788','Estrategia de marketing digital para redes sociales','Diseño una estrategia completa de marketing digital para tus redes sociales. Incluye análisis de audiencia, calendario de contenido para 1 mes, lineamientos gráficos y recomendaciones de pauta publicitaria.','marketing',450000,'10 días','["An\u00e1lisis de audiencia", "Calendario 30 d\u00edas", "Gu\u00eda de contenido", "Reporte de m\u00e9tricas"]','','publicado','2026-03-25 03:41:22.887017','2026-03-25 03:41:22.887033','74855607eeae4697b691f529c557928e');
INSERT INTO "publicaciones_publicacion" VALUES('c378190fb7ea46fa81ddb89ea5a91d9c','Redacción de artículos SEO para blog corporativo','Escribo artículos optimizados para posicionamiento en buscadores. Cada artículo incluye investigación de keywords, estructura SEO, meta descripción y enlaces internos sugeridos.','redaccion',120000,'3 días','["Investigaci\u00f3n de keywords", "Art\u00edculo de 1500+ palabras", "Meta descripci\u00f3n", "Im\u00e1genes sugeridas"]','','publicado','2026-03-25 03:41:22.889679','2026-03-25 03:41:22.889716','0b1a4894eb454d4eb828de133bb84718');
INSERT INTO "publicaciones_publicacion" VALUES('d2b18335d84347e885caf4cfd96e6457','Edición profesional de video para YouTube','Edito videos con calidad profesional para canales de YouTube. Incluye corrección de color, transiciones, subtítulos, música de fondo libre de derechos y thumbnail personalizado.','video',350000,'4 días','["Correcci\u00f3n de color", "Subt\u00edtulos", "M\u00fasica libre de derechos", "Thumbnail personalizado"]','','publicado','2026-03-25 03:41:22.891891','2026-03-25 03:41:22.891908','47b77c4f44014e43bf45a394461a2892');
INSERT INTO "publicaciones_publicacion" VALUES('4973aa1fe0764f0abcd67d6ee541c6d3','Desarrollo de API REST con Django y PostgreSQL','Diseño y desarrollo APIs RESTful robustas usando Django REST Framework. Incluye autenticación JWT, documentación Swagger, tests unitarios y despliegue en contenedor Docker.','desarrollo',1200000,'14 días','["Autenticaci\u00f3n JWT", "Documentaci\u00f3n Swagger", "Tests unitarios", "Docker"]','','publicado','2026-03-25 03:41:22.894326','2026-03-25 03:41:22.894341','967369eac6564d539dc06d43373a2a57');
INSERT INTO "publicaciones_publicacion" VALUES('3d3a812c29104195aabc1114dbe0ff86','Diseño de interfaz UI/UX para aplicación móvil','Diseño interfaces intuitivas y atractivas para aplicaciones móviles. Proceso completo: wireframes, prototipos interactivos en Figma y sistema de diseño reutilizable.','diseno',900000,'12 días','["Wireframes", "Prototipo interactivo Figma", "Sistema de dise\u00f1o", "Handoff para desarrollo"]','','publicado','2026-03-25 03:41:22.896414','2026-03-25 03:41:22.896429','e38db71366f748d6b2b7f7946bc709d4');
INSERT INTO "publicaciones_publicacion" VALUES('7249a1ad6653474799188f79e7250fb3','Gestión de campañas en Google Ads','Configuro y optimizo campañas de Google Ads para maximizar tu ROI. Incluye investigación de keywords, creación de anuncios, segmentación de audiencia y reportes semanales de rendimiento.','marketing',600000,'30 días','["Configuraci\u00f3n de campa\u00f1as", "Investigaci\u00f3n de keywords", "Reportes semanales", "Optimizaci\u00f3n continua"]','','publicado','2026-03-25 03:41:22.898756','2026-03-25 03:41:22.898771','74855607eeae4697b691f529c557928e');
INSERT INTO "publicaciones_publicacion" VALUES('3ba8035a04c34fde826cdbd902f6d40e','Traducción profesional español-inglés de documentos','Ofrezco traducciones precisas y naturales entre español e inglés. Especialidad en documentos técnicos, legales y de marketing. Revisión por segundo traductor incluida.','redaccion',80000,'2 días','["Traducci\u00f3n profesional", "Revisi\u00f3n por par", "Formato preservado", "Glosario de t\u00e9rminos"]','','publicado','2026-03-25 03:41:22.901398','2026-03-25 03:41:22.901415','0b1a4894eb454d4eb828de133bb84718');
INSERT INTO "publicaciones_publicacion" VALUES('77666f67e9004f8db44e004d8590ed2a','Creación de motion graphics para redes sociales','Creo animaciones cortas y atractivas para Instagram, TikTok y LinkedIn. Perfectas para anuncios, explicaciones de producto o contenido de marca.','video',400000,'5 días','["Animaci\u00f3n hasta 30 segundos", "M\u00fasica incluida", "3 formatos (1:1, 9:16, 16:9)", "1 revisi\u00f3n"]','','publicado','2026-03-25 03:41:22.903541','2026-03-25 03:41:22.903555','47b77c4f44014e43bf45a394461a2892');
INSERT INTO "publicaciones_publicacion" VALUES('7e75a8fa6c4749a490bdc2786978c381','Desarrollo de tienda online con Shopify','Configuro tu tienda en Shopify desde cero: diseño personalizado, integración de pasarela de pagos, catálogo de productos y optimización móvil.','desarrollo',1500000,'15 días','["Dise\u00f1o personalizado", "Pasarela de pagos", "Hasta 50 productos", "Capacitaci\u00f3n"]','','publicado','2026-03-25 03:41:22.905590','2026-03-25 03:41:22.905605','0b64bec995e54b8a9aba5ccce9527c44');
INSERT INTO "publicaciones_publicacion" VALUES('5ee7006181ae42ebba0709003bf87047','Consultoría SEO y auditoría de sitio web','Realizo una auditoría completa de tu sitio web enfocada en SEO técnico, contenido y autoridad de dominio. Entrego un plan de acción priorizado con recomendaciones concretas.','marketing',350000,'7 días','["Auditor\u00eda t\u00e9cnica", "An\u00e1lisis de contenido", "An\u00e1lisis de backlinks", "Plan de acci\u00f3n"]','','publicado','2026-03-25 03:41:22.907681','2026-03-25 03:41:22.907698','74855607eeae4697b691f529c557928e');
INSERT INTO "publicaciones_publicacion" VALUES('8637f07cf9164bacac06a102bc6bb875','Diseño de presentaciones corporativas en PowerPoint','Diseño presentaciones visualmente impactantes para reuniones, pitch decks e informes. Plantillas editables con tu identidad de marca.','diseno',180000,'3 días','["Hasta 20 slides", "Plantilla editable", "Iconograf\u00eda personalizada", "Versi\u00f3n PDF"]','','publicado','2026-03-25 03:41:22.909929','2026-03-25 03:41:22.909944','e38db71366f748d6b2b7f7946bc709d4');
INSERT INTO "publicaciones_publicacion" VALUES('a01d6415097c40ada2474c933f9530f0','Automatización de procesos con Python y scripts','Automatizo tareas repetitivas de tu negocio: scraping de datos, generación de reportes, procesamiento de archivos y más. Soluciones a medida con Python.','desarrollo',500000,'7 días','["Script personalizado", "Documentaci\u00f3n", "Soporte 1 semana", "C\u00f3digo fuente"]','','publicado','2026-03-25 03:41:22.912096','2026-03-25 03:41:22.912126','967369eac6564d539dc06d43373a2a57');
INSERT INTO "publicaciones_publicacion" VALUES('e58c007444164e4b831c6941030bf151','Redacción de copy para landing pages y ads','Escribo textos persuasivos que convierten visitantes en clientes. Especialidad en landing pages, anuncios de Facebook/Google y emails.','redaccion',150000,'3 días','["Copy para landing page", "Variantes A/B", "CTA optimizados", "Headlines"]','','publicado','2026-03-25 03:41:22.914750','2026-03-25 03:41:22.914765','0b1a4894eb454d4eb828de133bb84718');
